begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(10);
insert into auth.users(id,email,email_confirmed_at) values ('00000000-0000-0000-0000-0000000000d1','notify-a@example.invalid',now()),('00000000-0000-0000-0000-0000000000d2','notify-c@example.invalid',now());
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000d1',true);
set local role authenticated;
do $$begin perform set_config('test.notify_house',public.create_household('Prueba de aviso')::text,true);end$$;
reset role;set local role anon;
select throws_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,'42501',null,'anónimo no puede programar prueba');
reset role;set local role authenticated;
select throws_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,null,null,'se requiere preferencia habilitada');
insert into public.notification_preferences(household_id,user_id,preferences) values(current_setting('test.notify_house')::uuid,auth.uid(),'{"enabled":true,"channels":["push"],"summary":true}');
select throws_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,null,null,'se requiere dispositivo vinculado');
select public.register_push_subscription(current_setting('test.notify_house')::uuid,jsonb_build_object('endpoint','https://fcm.googleapis.com/luzradar-test', 'keys',jsonb_build_object('p256dh','B'||repeat('A',86),'auth',repeat('A',22))));
select lives_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,'se programa prueba para el usuario vinculado');
reset role;
select is((select count(*)::integer from public.notification_deliveries where user_id='00000000-0000-0000-0000-0000000000d1' and channel='push'),1,'se crea una entrega propia');
set local role authenticated;
select lives_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,'segunda prueba permitida');
select lives_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,'tercera prueba permitida');
select throws_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,null,null,'pruebas limitadas por hora');
reset role;select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000d2',true);set local role authenticated;
select throws_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'push')$$,null,null,'otro hogar no puede solicitar prueba');
select throws_ok($$select public.request_notification_test(current_setting('test.notify_house')::uuid,'otro')$$,null,null,'canal inválido rechazado');
reset role;select * from finish();rollback;
